dict(id="the-adhan", title="The words called out five times a day",
     lede="Taught word by word to Abū Maḥdhūrah, whose voice he ﷺ had liked.",
     src=dict(kind="hadith", coll="muslim", num=842, anchor="اللَّهُ أَكْبَرُ اللَّهُ أَكْبَرُ"),
     translit="Allāhu akbar, Allāhu akbar. Ashhadu an lā ilāha illa-llāh. Ashhadu anna Muḥammadan rasūlu-llāh. Ḥayya ʿala-ṣ-ṣalāh, ḥayya ʿala-l-falāḥ. Allāhu akbar, Allāhu akbar. Lā ilāha illa-llāh.",
     trans="Allah is greatest, Allah is greatest. I testify that there is no god but Allah. I testify that Muhammad is the Messenger of Allah. Come to the prayer. Come to success. Allah is greatest, Allah is greatest. There is no god but Allah.",
     story="Two of the lines are statements about who Allah is. Two are invitations, and they are the only imperatives in it: come to the prayer, come to success. The second names what the first one is.",
     note="Abū Maḥdhūrah had been mocking the call when the Prophet heard him, called him over, and taught it to him properly. He became the mu'adhdhin of Makkah.",
     tags=["adhan","athan","call to prayer","prayer time","learning","teach","children","muezzin","masjid","memorise","words","salah","hear it"]),

