     translit="As-salāmu ʿalaykum wa raḥmatu-Llāhi wa barakātuh",
     trans="Peace be upon you, and the mercy of Allah, and His blessings.",
     story="To his right he said all three. To his left he said the first two. The prayer does not stop; it is handed outward to whoever is there.",
