     translit="Tunkaḥu-l-marʾatu li-arbaʿ: li-mālihā wa li-ḥasabihā wa jamālihā wa li-dīnihā. Fa-ẓfar bi-dhāti-d-dīn",
     trans="A woman is married for four things: her wealth, her family standing, her beauty, and her religion. So win the one with religion.",
     mode="teaching",
     story="He does not deny the other three are reasons people marry. He lists them first, accurately, and then says which one to choose on.",
