dict(id="her-silence-is-her-permission", title="Nobody is married without being asked",
     lede="They asked how a shy answer would be recognised.",
     src=dict(kind="hadith", coll="bukhari", num=5136, anchor="لاَ تُنْكَحُ الأَيِّمُ حَتَّى تُسْتَأْمَرَ",
              span="لاَ تُنْكَحُ الأَيِّمُ حَتَّى تُسْتَأْمَرَ وَلاَ تُنْكَحُ الْبِكْرُ حَتَّى تُسْتَأْذَنَ"),
     translit="Lā tunkaḥu-l-ayyimu ḥattā tustaʾmar, wa lā tunkaḥu-l-bikru ḥattā tustaʾdhan",
     trans="A previously married woman is not given in marriage until she is consulted, and a woman who has not married before is not given in marriage until her permission is sought.",
     mode="teaching",
     story="They said: Messenger of Allah, how is her permission given? He said: that she stays silent. Two different verbs are used, one for each, and both of them mean asking.",
     tags=["marriage","consent","forced","permission","asked","choice","arranged","family","pressure","refuse","rights","silence"]),

dict(id="the-falsest-talk", title="What he named as the least reliable speech there is",
     lede="Four prohibitions, then one instruction.",
     src=dict(kind="hadith", coll="bukhari", num=5144, anchor="إِيَّاكُمْ وَالظَّنَّ، فَإِنَّ الظَّنَّ أَكْذَبُ الْحَدِيثِ",
              span="إِيَّاكُمْ وَالظَّنَّ، فَإِنَّ الظَّنَّ أَكْذَبُ الْحَدِيثِ، وَلاَ تَجَسَّسُوا، وَلاَ تَحَسَّسُوا، وَلاَ تَبَاغَضُوا، وَكُونُوا إِخْوَانًا"),
     translit="Iyyākum wa-ẓ-ẓann, fa-inna-ẓ-ẓanna akdhabu-l-ḥadīth. Wa lā tajassasū, wa lā taḥassasū, wa lā tabāghaḍū, wa kūnū ikhwānā",
     trans="Beware of assumption, for assumption is the falsest speech. Do not spy, do not pry, do not hate one another. And be brothers.",
     mode="teaching",
     story="Assumption is not called a bad habit or a weakness. It is put in the category of speech, and then ranked as the least true kind there is, below outright lying.",
     tags=["assume","suspicion","think","spy","snoop","gossip","wrong","imagine","jealous","trust","paranoid","checking"]),

dict(id="like-a-rib", title="What happens if you try to straighten it",
     lede="Two outcomes, and only one of them keeps the thing.",
     src=dict(kind="hadith", coll="bukhari", num=5184, anchor="الْمَرْأَةُ كَالضِّلَعِ",
              span="الْمَرْأَةُ كَالضِّلَعِ، إِنْ أَقَمْتَهَا كَسَرْتَهَا، وَإِنِ اسْتَمْتَعْتَ بِهَا اسْتَمْتَعْتَ بِهَا وَفِيهَا عِوَجٌ"),
     translit="Al-marʾatu ka-ḍ-ḍilaʿ. In aqamtahā kasartahā, wa ini-stamtaʿta bihā-stamtaʿta bihā wa fīhā ʿiwaj",
     trans="A woman is like a rib. If you try to straighten it you break it. And if you take comfort in it, you take comfort in it while it still has its curve.",
     mode="teaching",
     story="A rib is curved because that is the shape that does the job. Straightening it does not improve it, it destroys it, and the thing it was protecting with it.",
     tags=["marriage","wife","change","accept","fix","argument","different","expectations","patience","husband","compromise","who they are"]),

dict(id="every-one-of-you-is-a-guardian", title="Nobody in the list is exempt",
     lede="It runs from the ruler down and back up again.",
     src=dict(kind="hadith", coll="bukhari", num=5188, anchor="كُلُّكُمْ رَاعٍ وَكُلُّكُمْ مَسْئُولٌ",
              span="كُلُّكُمْ رَاعٍ وَكُلُّكُمْ مَسْئُولٌ، فَالإِمَامُ رَاعٍ وَهْوَ مَسْئُولٌ وَالرَّجُلُ رَاعٍ عَلَى أَهْلِهِ وَهْوَ مَسْئُولٌ وَالْمَرْأَةُ رَاعِيَةٌ عَلَى بَيْتِ زَوْجِهَا وَهْىَ مَسْئُولَةٌ"),
     translit="Kullukum rāʿin wa kullukum masʾūl. Fa-l-imāmu rāʿin wa huwa masʾūl, wa-r-rajulu rāʿin ʿalā ahlihi wa huwa masʾūl, wa-l-marʾatu rāʿiyatun ʿalā bayti zawjihā wa hiya masʾūlah",
     trans="Every one of you is a shepherd and every one of you is responsible. The leader is a shepherd and is responsible. A man is a shepherd over his household and is responsible. A woman is a shepherd over her husband's house and is responsible.",
     mode="teaching",
     story="It ends where it began: so all of you are shepherds and all of you are responsible. The same two words are applied to everybody in the list, in the same grammar.",
     tags=["responsibility","family","home","work","leader","accountable","looking after","duty","role","parents","charge","everyone"]),

